// Every category folder exports `default` = array of component definitions from its index.js.
// Categories load independently so one broken file can't take down the whole page.
export const CATEGORIES = [
  'core',
  'big-tech',
  'creative',
  'retro',
  'menus',
  'inputs',
  'physical',
  'modern-brands',
  'motion',
  'shaders',
  'typography',
  'depth',
  'game-ui',
  'obscure-web',
  'libraries',
  'automotive',
  'kiosks',
  'scifi',
  'industrial',
  'toys',
];

// components/bundle.js (generated by scripts/build.mjs) carries every module in one request instead of
// ~700. Deployed pages load it; localhost loads the per-file modules so edits show up on reload.
// `?bundle=1` / `?bundle=0` force either way.
function wantBundle() {
  try {
    const q = new URLSearchParams(location.search).get('bundle');
    if (q !== null) return q !== '0';
    return !/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname);
  } catch {
    return false;
  }
}

async function loadGroups() {
  if (wantBundle()) {
    try {
      return (await import('./bundle.js')).default;
    } catch (e) {
      console.warn('[buttons] bundle failed to load, falling back to category modules', e);
    }
  }
  const results = await Promise.allSettled(
    CATEGORIES.map((c) => import(`./${c}/index.js`).then((m) => ({ cat: c, list: m.default })))
  );
  const groups = [];
  for (const r of results) {
    if (r.status !== 'fulfilled') console.error('[buttons] category failed to load', r.reason);
    else groups.push(r.value);
  }
  return groups;
}

export async function loadComponents() {
  const seen = new Set();
  const out = [];
  for (const { cat: c, list } of await loadGroups()) {
    if (!Array.isArray(list)) {
      console.error(`[buttons] category "${c}" did not export an array`);
      continue;
    }
    for (const def of list) {
      if (!def || typeof def !== 'object' || !def.id) continue;
      if (seen.has(def.id)) {
        console.warn(`[buttons] duplicate id "${def.id}" in "${c}" skipped`);
        continue;
      }
      seen.add(def.id);
      def._cat = c;
      out.push(def);
    }
  }
  return out;
}
